INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('ffed5b73-6714-4a5d-bcfd-649a6ad5a7dc', 'c3c3c3c3-3030-4000-8000-000000000003', 23, 'Dia 23 — Rotina', 'Semana 4: Integrar', '{"pch": "Daniel orava tr\u00eas vezes ao dia\u2026 Rotina sagrada cria espa\u00e7o para clareza.", "verse": "Dn 6,10", "lectio": "Leia Dn 6,6-13. A fidelidade de Daniel.", "practice": "Crie uma rotina matinal de 15 min: sil\u00eancio, leitura, ora\u00e7\u00e3o.", "question": "Como \u00e9 sua rotina matinal? Ela alimenta ou drena sua mente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;